  border-radius: 8px;
  position: relative;
  user-select: none;
  white-space: nowrap;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.func-sidebar-item:hover {
  background: color-mix(in srgb, var(--theme-primary) 6%, white);
  color: color-mix(in srgb, var(--theme-primary) 90%, #111827);
}

.dark .func-sidebar-item:hover {
  background: color-mix(in srgb, var(--theme-primary) 12%, #1f2937);
  color: color-mix(in srgb, var(--theme-primary) 90%, #f3f4f6);
}

.func-sidebar-item:active {
  background: color-mix(in srgb, var(--theme-primary) 12%, white);
}

.dark .func-sidebar-item:active {
  background: color-mix(in srgb, var(--theme-primary) 20%, #1f2937);
}

