}

.prose h2 {
  font-size: 1.75em;
  font-weight: 600;
  margin-top: 1.25em;
  margin-bottom: 0.5em;
  color: #1a1a1a;
  line-height: 1.3;
}

.prose h3 {
  font-size: 1.375em;
  font-weight: 600;
  margin-top: 1em;
  margin-bottom: 0.5em;
  color: #374151;
  line-height: 1.4;
}

.prose h1:first-child,
.prose h2:first-child,
.prose h3:first-child,
.prose p:first-child {
  margin-top: 0;
}

.prose p {
  margin-top: 0;
  margin-bottom: 0.75em;
  line-height: 1.75;
  color: #374151;
}

.prose ul {
  list-style-type: disc;
  padding-left: 1.5em;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
}

.prose ol {
  list-style-type: decimal;
  padding-left: 1.5em;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
}

