  padding-left: 1.5em;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
}

.prose li {
  margin-bottom: 0.25em;
  line-height: 1.75;
}

.prose blockquote {
  border-left: 4px solid var(--color-primary);
  padding-left: 1em;
  margin-left: 0;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
  color: #6b7280;
