  background: #1a1a1a;
  color: #e5e7eb;
  padding: 1em;
  border-radius: 0.5rem;
  overflow-x: auto;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
  font-family: "JetBrains Mono", "Fira Code", Monaco, monospace;
  font-size: 0.875em;
  line-height: 1.7;
}

.prose code {
  background: #f3f4f6;
  padding: 0.2em 0.4em;
  border-radius: 0.25rem;
  font-family: "JetBrains Mono", "Fira Code", Monaco, monospace;
  font-size: 0.875em;
  color: #1a1a1a;
}

.prose pre code {
  background: transparent;
  padding: 0;
  color: inherit;
}

.prose b, .prose strong {
  font-weight: 700;
  color: #1a1a1a;
}

.prose a {
