  font-size: 1.375em;
  font-weight: 600;
  margin-top: 1em;
  margin-bottom: 0.5em;
  color: #374151;
  line-height: 1.4;
}

.prose h1:first-child,
.prose h2:first-child,
.prose h3:first-child,
.prose p:first-child {
  margin-top: 0;
}

.prose p {
  margin-top: 0;
  margin-bottom: 0.75em;
  line-height: 1.75;
  color: #374151;
}

.prose ul {
  list-style-type: disc;
  padding-left: 1.5em;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
}

.prose ol {
  list-style-type: decimal;
  padding-left: 1.5em;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
}

.prose li {
  margin-bottom: 0.25em;
  line-height: 1.75;
}

.prose blockquote {
  border-left: 4px solid var(--color-primary);
  padding-left: 1em;
  margin-left: 0;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
  color: #6b7280;
  font-style: italic;
}

.prose pre {
  background: #1a1a1a;
  color: #e5e7eb;
  padding: 1em;
  border-radius: 0.5rem;
  overflow-x: auto;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
  font-family: "JetBrains Mono", "Fira Code", Monaco, monospace;
  font-size: 0.875em;
  line-height: 1.7;
}

.prose code {
  background: #f3f4f6;
  padding: 0.2em 0.4em;
  border-radius: 0.25rem;
  font-family: "JetBrains Mono", "Fira Code", Monaco, monospace;
  font-size: 0.875em;
  color: #1a1a1a;
}

.prose pre code {
  background: transparent;
  padding: 0;
  color: inherit;
}

.prose b, .prose strong {
  font-weight: 700;
  color: #1a1a1a;
}

.prose a {
  color: var(--color-primary);
