  padding: 20px 24px;
  margin-bottom: 1em;
  border-left: 5px solid #22c55e;
}

.prose .info-box h3 {
  margin-top: 0;
  color: #15803d;
}

.prose .info-box p,
.prose .info-box li {
  color: #166534;
}

