  font-size: 1.375em;
  font-weight: 600;
  margin-top: 1em;
  margin-bottom: 0.5em;
  color: #374151;
  line-height: 1.4;
}

.prose h1:first-child,
.prose h2:first-child,
.prose h3:first-child,
.prose p:first-child {
  margin-top: 0;
}

