  background: #1a1a1a;
  color: #e5e7eb;
  padding: 1em;
  border-radius: 0.5rem;
  overflow-x: auto;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
  font-family: "JetBrains Mono", "Fira Code", Monaco, monospace;
  font-size: 0.875em;
  line-height: 1.7;
}

