  margin-top: 0.75em;
  margin-bottom: 0.75em;
}

.prose ol {
  list-style-type: decimal;
  padding-left: 1.5em;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
}

.prose li {
  margin-bottom: 0.25em;
  line-height: 1.75;
}

.prose blockquote {
  border-left: 4px solid var(--color-primary);
  padding-left: 1em;
  margin-left: 0;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
  color: #6b7280;
  font-style: italic;
}

.prose pre {
  background: #1a1a1a;
  color: #e5e7eb;
  padding: 1em;
  border-radius: 0.5rem;
  overflow-x: auto;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
  font-family: "JetBrains Mono", "Fira Code", Monaco, monospace;
  font-size: 0.875em;
  line-height: 1.7;
}

.prose code {
  background: #f3f4f6;
  padding: 0.2em 0.4em;
  border-radius: 0.25rem;
  font-family: "JetBrains Mono", "Fira Code", Monaco, monospace;
  font-size: 0.875em;
  color: #1a1a1a;
}

.prose pre code {
  background: transparent;
  padding: 0;
  color: inherit;
}

.prose b, .prose strong {
  font-weight: 700;
  color: #1a1a1a;
}

.prose a {
  color: var(--color-primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.prose a:hover {
  color: var(--color-primary-dark);
}

.prose hr {
  border: none;
  border-top: 2px solid #e5e7eb;
  margin: 1.5em 0;
}

/* Info box */
.prose .info-box {
  background: linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%);
  border-radius: 16px;
  padding: 20px 24px;
  margin-bottom: 1em;
  border-left: 5px solid #22c55e;
}

.prose .info-box h3 {
  margin-top: 0;
  color: #15803d;
}

.prose .info-box p,
.prose .info-box li {
  color: #166534;
}

