@import "tailwindcss";

@theme {
  --color-primary: var(--theme-primary, #FF743D);
  --color-primary-dark: var(--theme-primary-dark, #ea580c);
  --color-near-black: #1a1a1a;
  --color-text-secondary: #374151;
  --color-text-gray: #6b7280;
  --color-bg-sidebar: #f9fafb;
  --color-bg-hover: #f3f4f6;
  --color-bg-light: #f5f5f5;
  --color-border-gray: #e5e7eb;
  --color-active-bg: color-mix(in srgb, var(--theme-primary) 8%, white);
  --color-blue-title: #2563eb;
  --color-green-info: #22c55e;
  --color-cyan-title: #0891b2;
  --color-gray-100: #f3f4f6;
  --color-gray-200: #e5e7eb;
  --color-gray-300: #d1d5db;
  --color-gray-400: #9ca3af;
  --color-gray-500: #6b7280;
  --color-gray-600: #4b5563;
  --color-gray-700: #374151;
  --color-gray-800: #1f2937;
  --color-gray-900: #111827;
}

:root {
  --theme-primary: #FF743D;
  --theme-primary-dark: #ea580c;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans SC", sans-serif, "Noto Color Emoji";
  background: #ffffff;
  color: #1a1a1a;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* Sidebar styles */
.func-sidebar {
  width: 56px;
  min-width: 56px;
  height: 100vh;
  background: color-mix(in srgb, var(--theme-primary) 3%, white);
  border-right: 1px solid color-mix(in srgb, var(--theme-primary) 10%, #e5e7eb);
  display: flex;
  flex-direction: column;
  padding: 20px 8px 0;
  overflow: hidden;
  transition: width 0.25s ease, min-width 0.25s ease;
}

.dark .func-sidebar {
  background: color-mix(in srgb, var(--theme-primary) 5%, #111827);
  border-right: 1px solid color-mix(in srgb, var(--theme-primary) 15%, #374151);
}

.func-sidebar.expanded {
  width: 172px;
  min-width: 172px;
}

.func-section-title {
  display: flex;
  align-items: center;
  padding: 0 8px;
  height: 28px;
  opacity: 1;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: color-mix(in srgb, var(--theme-primary) 50%, #9ca3af);
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  transition: height 0.25s ease, opacity 0.2s ease;
}

.func-sidebar:not(.expanded) .func-section-title {
  height: 0;
  opacity: 0;
}

.func-section-title:hover {
  color: color-mix(in srgb, var(--theme-primary) 70%, #6b7280);
}

.func-chevron {
  width: 14px;
  height: 14px;
  margin-right: 6px;
  transition: transform 0.2s ease;
  flex-shrink: 0;
}

.func-chevron.collapsed {
  transform: rotate(-90deg);
}

.func-section-items {
  overflow: hidden;
  max-height: 200px;
  opacity: 1;
  transition: max-height 0.3s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.25s ease, margin 0.3s ease;
}

.func-section-items.collapsed {
  max-height: 0;
  opacity: 0;
}

.func-sidebar-item {
  display: flex;
  align-items: center;
  width: 100%;
  height: 40px;
  padding: 0 10px;
  margin: 2px 0;
  cursor: pointer;
  text-decoration: none;
  color: color-mix(in srgb, var(--theme-primary) 70%, #6b7280);
  border-radius: 8px;
  position: relative;
  user-select: none;
  white-space: nowrap;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.func-sidebar-item:hover {
  background: color-mix(in srgb, var(--theme-primary) 6%, white);
  color: color-mix(in srgb, var(--theme-primary) 90%, #111827);
}

.dark .func-sidebar-item:hover {
  background: color-mix(in srgb, var(--theme-primary) 12%, #1f2937);
  color: color-mix(in srgb, var(--theme-primary) 90%, #f3f4f6);
}

.func-sidebar-item:active {
  background: color-mix(in srgb, var(--theme-primary) 12%, white);
}

.dark .func-sidebar-item:active {
  background: color-mix(in srgb, var(--theme-primary) 20%, #1f2937);
}

.func-sidebar-item.active {
  color: var(--color-primary-dark);
  background: var(--color-active-bg);
}



.func-sidebar.expanded .func-sidebar-item.active::before {
  content: '';
  position: absolute;
  left: -8px;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 18px;
  background: var(--color-primary-dark);
  border-radius: 0 3px 3px 0;
}

.func-sidebar-icon {
  width: 20px;
  height: 20px;
  min-width: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.func-sidebar-icon svg {
  width: 20px;
  height: 20px;
}

.func-sidebar-text {
  visibility: hidden;
  width: 0;
  margin-left: 0;
  overflow: hidden;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.func-sidebar.expanded .func-sidebar-text {
  visibility: visible;
  width: auto;
  margin-left: 10px;
  opacity: 1;
}

.func-sidebar-divider {
  height: 1px;
  background: #e5e7eb;
  margin: 8px 10px;
}

/* Prose content styles */
.prose h1 {
  font-size: 2.25em;
  font-weight: 700;
  margin-top: 1.5em;
  margin-bottom: 0.5em;
  color: #1a1a1a;
  line-height: 1.3;
}

.prose h2 {
  font-size: 1.75em;
  font-weight: 600;
  margin-top: 1.25em;
  margin-bottom: 0.5em;
  color: #1a1a1a;
  line-height: 1.3;
}

.prose h3 {
  font-size: 1.375em;
  font-weight: 600;
  margin-top: 1em;
  margin-bottom: 0.5em;
  color: #374151;
  line-height: 1.4;
}

.prose h1:first-child,
.prose h2:first-child,
.prose h3:first-child,
.prose p:first-child {
  margin-top: 0;
}

.prose p {
  margin-top: 0;
  margin-bottom: 0.75em;
  line-height: 1.75;
  color: #374151;
}

.prose ul {
  list-style-type: disc;
  padding-left: 1.5em;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
}

.prose ol {
  list-style-type: decimal;
  padding-left: 1.5em;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
}

.prose li {
  margin-bottom: 0.25em;
  line-height: 1.75;
}

.prose blockquote {
  border-left: 4px solid var(--color-primary);
  padding-left: 1em;
  margin-left: 0;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
  color: #6b7280;
  font-style: italic;
}

.prose pre {
  background: #1a1a1a;
  color: #e5e7eb;
  padding: 1em;
  border-radius: 0.5rem;
  overflow-x: auto;
  margin-top: 0.75em;
  margin-bottom: 0.75em;
  font-family: "JetBrains Mono", "Fira Code", Monaco, monospace;
  font-size: 0.875em;
  line-height: 1.7;
}

.prose code {
  background: #f3f4f6;
  padding: 0.2em 0.4em;
  border-radius: 0.25rem;
  font-family: "JetBrains Mono", "Fira Code", Monaco, monospace;
  font-size: 0.875em;
  color: #1a1a1a;
}

.prose pre code {
  background: transparent;
  padding: 0;
  color: inherit;
}

.prose b, .prose strong {
  font-weight: 700;
  color: #1a1a1a;
}

.prose a {
  color: var(--color-primary);
  text-decoration: underline;
  text-underline-offset: 2px;
}

.prose a:hover {
  color: var(--color-primary-dark);
}

.prose hr {
  border: none;
  border-top: 2px solid #e5e7eb;
  margin: 1.5em 0;
}

/* Info box */
.prose .info-box {
  background: linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%);
  border-radius: 16px;
  padding: 20px 24px;
  margin-bottom: 1em;
  border-left: 5px solid #22c55e;
}

.prose .info-box h3 {
  margin-top: 0;
  color: #15803d;
}

.prose .info-box p,
.prose .info-box li {
  color: #166534;
}

/* Animations */
@keyframes slide-down {
  0% { opacity: 0; transform: translateY(-10px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes fade-in {
  0% { opacity: 0; }
  100% { opacity: 1; }
}

@keyframes pop-in {
  0% { opacity: 0; transform: scale(0.8); }
  70% { transform: scale(1.05); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes pop-out {
  0% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.8); }
}

@keyframes slide-in-right {
  0% { opacity: 0; transform: translateX(-8px); }
  100% { opacity: 1; transform: translateX(0); }
}

@keyframes ripple {
  0% { transform: scale(0); opacity: 0.5; }
  100% { transform: scale(4); opacity: 0; }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--color-primary) 40%, transparent); }
  50% { box-shadow: 0 0 0 8px color-mix(in srgb, var(--color-primary) 0%, transparent); }
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-3px); }
  75% { transform: translateX(3px); }
}

@keyframes height-expand {
  0% { max-height: 0; opacity: 0; }
  100% { max-height: 1000px; opacity: 1; }
}

@keyframes height-collapse {
  0% { max-height: 1000px; opacity: 1; }
  100% { max-height: 0; opacity: 0; }
}

@keyframes jelly-in {
  0% { opacity: 0; transform: scale(0.3); }
  40% { opacity: 1; transform: scale(1.1); }
  60% { transform: scale(0.95); }
  80% { transform: scale(1.02); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes stagger-in {
  0% { 
    opacity: 0; 
    transform: translateX(-16px) scale(0.95); 
  }
  40% { 
    transform: translateX(3px) scale(1.02); 
  }
  70% {
    transform: translateX(-1px) scale(0.99);
  }
  100% { 
    opacity: 1; 
    transform: translateX(0) scale(1); 
  }
}

@keyframes stagger-out {
  0% { 
    opacity: 1; 
    transform: translateX(0) scale(1); 
  }
  100% { 
    opacity: 0; 
    transform: translateX(-16px) scale(0.95); 
  }
}

@keyframes chevron-rotate {
  0% { transform: rotate(0deg); }
  50% { transform: rotate(110deg); }
  70% { transform: rotate(85deg); }
  100% { transform: rotate(90deg); }
}

@keyframes chevron-rotate-back {
  0% { transform: rotate(90deg); }
  50% { transform: rotate(-20deg); }
  70% { transform: rotate(10deg); }
  100% { transform: rotate(0deg); }
}

@keyframes page-slide-in {
  0% { opacity: 0; transform: translateY(-8px) scale(0.95); }
  60% { transform: translateY(2px) scale(1.01); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes page-slide-out {
  0% { opacity: 1; transform: translateY(0) scale(1); }
  100% { opacity: 0; transform: translateY(-8px) scale(0.95); }
}

.animate-slide-down {
  animation: slide-down 0.2s ease-out;
}

.animate-fade-in {
  animation: fade-in 0.3s ease-out;
}

.animate-pop-in {
  animation: pop-in 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.animate-pop-out {
  animation: pop-out 0.2s ease-in forwards;
}

