/* Animations */
@keyframes slide-down {
  0% { opacity: 0; transform: translateY(-10px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes fade-in {
  0% { opacity: 0; }
  100% { opacity: 1; }
}

@keyframes pop-in {
  0% { opacity: 0; transform: scale(0.8); }
  70% { transform: scale(1.05); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes pop-out {
  0% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.8); }
}

@keyframes slide-in-right {
  0% { opacity: 0; transform: translateX(-8px); }
  100% { opacity: 1; transform: translateX(0); }
}

@keyframes ripple {
  0% { transform: scale(0); opacity: 0.5; }
  100% { transform: scale(4); opacity: 0; }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--color-primary) 40%, transparent); }
  50% { box-shadow: 0 0 0 8px color-mix(in srgb, var(--color-primary) 0%, transparent); }
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-3px); }
  75% { transform: translateX(3px); }
}

@keyframes height-expand {
  0% { max-height: 0; opacity: 0; }
  100% { max-height: 1000px; opacity: 1; }
}

@keyframes height-collapse {
  0% { max-height: 1000px; opacity: 1; }
  100% { max-height: 0; opacity: 0; }
}

@keyframes jelly-in {
  0% { opacity: 0; transform: scale(0.3); }
  40% { opacity: 1; transform: scale(1.1); }
  60% { transform: scale(0.95); }
  80% { transform: scale(1.02); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes stagger-in {
  0% { 
    opacity: 0; 
    transform: translateX(-16px) scale(0.95); 
  }
  40% { 
    transform: translateX(3px) scale(1.02); 
  }
  70% {
    transform: translateX(-1px) scale(0.99);
  }
  100% { 
    opacity: 1; 
    transform: translateX(0) scale(1); 
  }
}

@keyframes stagger-out {
  0% { 
    opacity: 1; 
    transform: translateX(0) scale(1); 
  }
  100% { 
    opacity: 0; 
    transform: translateX(-16px) scale(0.95); 
  }
}

@keyframes chevron-rotate {
  0% { transform: rotate(0deg); }
  50% { transform: rotate(110deg); }
  70% { transform: rotate(85deg); }
  100% { transform: rotate(90deg); }
}

@keyframes chevron-rotate-back {
  0% { transform: rotate(90deg); }
  50% { transform: rotate(-20deg); }
  70% { transform: rotate(10deg); }
  100% { transform: rotate(0deg); }
}

@keyframes page-slide-in {
  0% { opacity: 0; transform: translateY(-8px) scale(0.95); }
  60% { transform: translateY(2px) scale(1.01); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes page-slide-out {
  0% { opacity: 1; transform: translateY(0) scale(1); }
  100% { opacity: 0; transform: translateY(-8px) scale(0.95); }
}

